  if($existing)q('UPDATE seller_reviews SET rating=?,review_text=?,updated_at=? WHERE id=?',[(int)$rating,$text,now(),$existing['id']]);
  else q('INSERT INTO seller_reviews (seller_id,user_id,rating,review_text,created_at,updated_at) VALUES (?,?,?,?,?,?)',[$s['user_id'],$reviewer['id'],(int)$rating,$text,now(),now()]);
  notify_review((int)$s['user_id'],null,t('Shop review received'),$s['business_name'].' · '.$rating.' stars','restaurant.php?id='.$s['id'].'#reviews');db()->commit();flash(t('Your review has been saved. Thank you for sharing.'));go('restaurant.php?id='.$s['id'].'#reviews');
 }
